function evidence = formal90_write_evidence( ...
    formalTaskId, modelPath, outDir, groupWeights, facts, measurementDependency)
%FORMAL90_WRITE_EVIDENCE Write one complete, score-free evidence document.
arguments
    formalTaskId (1,1) string
    modelPath (1,1) string
    outDir (1,1) string
    groupWeights (1,1) struct
    facts (1,1) struct
    measurementDependency (1,1) string
end
if ~isfolder(outDir), mkdir(outDir); end
stack = dbstack('-completenames');
if numel(stack) > 1
    extractorPath = string(stack(2).file);
else
    extractorPath = string(mfilename('fullpath')) + ".m";
end
[~, modelName, modelExt] = fileparts(modelPath);
[~, extractorName, extractorExt] = fileparts(extractorPath);
[~, dependencyName, dependencyExt] = fileparts(measurementDependency);
evidence = struct( ...
    'schema', "simuverity.formal90-evidence-input.v1", ...
    'formal_task_id', formalTaskId, ...
    'model_file', modelName + modelExt, ...
    'extractor_file', extractorName + extractorExt, ...
    'measurement_dependency_file', dependencyName + dependencyExt, ...
    'generated_at', string(datetime('now', 'TimeZone', 'UTC', ...
        'Format', 'yyyy-MM-dd''T''HH:mm:ssXXX')), ...
    'matlab_release', string(version('-release')), ...
    'platform_valid', logical(facts.platform_valid), ...
    'group_weights', struct('A', double(groupWeights.A), ...
        'Q', double(groupWeights.Q), 'M', double(groupWeights.M), ...
        'R', double(groupWeights.R), 'D', double(groupWeights.D)), ...
    'facts', facts, ...
    'score_fields_present', false);
path = fullfile(outDir, 'evidence.json');
fid = fopen(path, 'w', 'n', 'UTF-8');
assert(fid >= 0, 'Cannot open %s', path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(evidence, 'PrettyPrint', true), 'char');
end
